// before C# 4: Enter before try
Monitor.Enter(_gate);
// ← a ThreadAbortException could land here:
//   the lock is taken, finally does not guard it
try     { /* the lock body */ }
finally { Monitor.Exit(_gate); }

// since C# 4: Enter inside try
bool lockTaken = false;
try
{
    // lockTaken = true exactly when acquired
    Monitor.Enter(_gate, ref lockTaken);
    // the lock body
}
finally
{
    if (lockTaken) Monitor.Exit(_gate);
}

